    def solve(data):
        half_up = data["rounding"] == "half_up"

        def rounded(n, d=10000):
            return (n + d // 2) // d if half_up else n // d

        winners = {}
        cutoff = data.get("cutoff", 10**9)
        for pos, event in enumerate(data["events"]):
            seq = event.get("sequence", 0)
            if seq > cutoff:
                continue
            ident = event.get("id", "anonymous:" + str(pos))
            key = ((seq, event.get("revision", 0), pos) if sequence_first
                   else (event.get("revision", 0), pos))
            if ident not in winners or key > winners[ident][0]:
                winners[ident] = (key, event)

        balances = dict(data.get("opening", {}))
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount))
            base = net if discounted else raw
            total = net + rounded(base * event.get("tax_bp", 0))
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _resolver(data):
    from itertools import product

    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    rows = {name: {row["version"]: row for row in packages[name]} for name in names}
    choices = []
    for name in names:
        versions = sorted(v for v in rows[name]
                          if v not in blocked.get(name, [])
                          and (name not in pins or pins[name] == v))
        choices.append([-1] + versions)

    best = None
    best_versions = None
    for values in product(*choices):
        installed = {name: v for name, v in zip(names, values) if v != -1}
        if any(name not in installed or not bounds[0] <= installed[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue
        active, finished = set(), set()
        valid = True

        def visit(name):
            nonlocal valid
            if name in active:
                valid = False
                return
            if name in finished or not valid:
                return
            if name not in installed:
                valid = False
                return
            active.add(name)
            row = rows[name][installed[name]]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                version = installed.get(other)
                if version is None or not dep["min"] <= version <= dep["max"]:
                    valid = False
                    break
                visit(other)
                if not valid:
                    break
            active.remove(name)
            finished.add(name)

        for name, bounds in roots.items():
            if name in installed and not bounds[0] <= installed[name] <= bounds[1]:
                valid = False
                break
            visit(name)
            if not valid:
                break
        if not valid or finished != set(installed):
            continue
        if best is None or values < best:
            best = values
            best_versions = installed
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _jobs(data):
    from itertools import combinations

    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    for subset in combinations(jobs, k):
        ids = [job["id"] for job in subset]
        idset = set(ids)
        if idset & blocked or not mandatory <= idset:
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i]["end"] > ordered[i + 1]["start"]
               for i in range(len(ordered) - 1)):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        value = sum(job["value"] for job in subset)
        sorted_ids = sorted(ids)
        if (best_value is None or value > best_value
                or (value == best_value and sorted_ids < best_ids)):
            best_value, best_ids = value, sorted_ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _routes(data):
    import heapq

    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    start = data["source"]
    mask = bit.get(start, 0)
    remaining = data["coupons"]
    initial = (start, mask, remaining)
    dist = {initial: data["start"]}
    queue = [(data["start"], start, mask, remaining)]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        arrival, node, seen, left = heapq.heappop(queue)
        state = (node, seen, left)
        if dist.get(state) != arrival:
            continue
        if node == data["target"] and seen == full and left == 0:
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], left)]
            if left:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                options.append((duration, left - 1))
            for duration, new_left in options:
                time = depart + duration
                if time > data["deadline"]:
                    continue
                nxt = edge["v"]
                new_mask = seen | bit.get(nxt, 0)
                new_state = (nxt, new_mask, new_left)
                if time < dist.get(new_state, float("inf")):
                    dist[new_state] = time
                    heapq.heappush(queue, (time, nxt, new_mask, new_left))
    return {"arrival": None}


